CREATE TRIGGER
  Stor_TBI_OuTrn
  Before Insert
  On Stor_OuTrn
  For Each Row
BEGIN
  DECLARE nStr     DECIMAL(38,10);
  DECLARE nIcsId   DECIMAL(38,10);
  DECLARE nCst     DECIMAL(38,10);
  DECLARE nBCst    DECIMAL(38,10);
  DECLARE nQnt     DECIMAL(38,10);
  DECLARE nBRate   DECIMAL(38,10) := 0;
  Select Stor_Id, Decode(Sign(IFNULL(BCurn_Rate,1)), -1,1, 0,1, IFNULL(BCurn_Rate,1))
    Into nStr   , nBRate
    From Stor_OuMst
    Where Id=NEW.Mst_Id;
  nQnt := 0;
  nCst := 0;
  Select IFNULL(CQnt,0), IFNULL(CAmt,0), IFNULL(CBAmt,0)
    Into nQnt, nCst, nBCst
    From Stor_SMat
   Where Stor_Id=nStr
     And Item_Id=NEW.Item_Id;
  If nQnt>0 Then
    nCst  := nCst  / nQnt;
    nBCst := nBCst / nQnt;
  End If;
  SET NEW.BAmt = Round(IFNULL(NEW.Amt,0) / nBRate, 2);
  SET NEW.Cst = nCst  * NEW.Qnt;
  SET NEW.BCst = nBCst * NEW.Qnt;
  Update Stor_SMat Set
         CQnt =IFNULL(CQnt ,0)-IFNULL(NEW.Qnt ,0),
         CAmt =IFNULL(CAmt ,0)-IFNULL(NEW.Cst ,0),
         CBAmt=IFNULL(CBAmt,0)-IFNULL(NEW.BCst,0)
   Where Stor_Id=nStr
     And Item_Id=NEW.Item_Id;
  SET NEW.LotSer = IFNULL(NEW.LotSer  ,'-');
  SET NEW.Model_Id = IFNULL(NEW.Model_Id,0  );
  SET NEW.Color_Id = IFNULL(NEW.Color_Id,0  );
  SET NEW.Size_Id = IFNULL(NEW.Size_Id ,0  );
  SET NEW.nLength = IFNULL(NEW.nLength ,0  );
  SET NEW.nWidth = IFNULL(NEW.nWidth  ,0  );
  SET NEW.nHeight = IFNULL(NEW.nHeight ,0  );
  nIcsId := get_ICS_Id(NEW.Item_Id, NEW.LotSer , NEW.Unit_Id, NEW.Model_Id, NEW.Size_Id, NEW.Color_Id, NEW.nLength, NEW.nWidth, NEW.nHeight);
  IF nIcsId>0 Then
    Begin
      UPDATE Stor_ICS SET
             CQnt =IFNULL(CQnt ,0)-IFNULL(NEW.Qnt ,0),
             CWQnt=IFNULL(CWQnt,0)-IFNULL(NEW.WQnt,0),
             CCst =IFNULL(CCst ,0)-IFNULL(NEW.Cst ,0),
             CBCst=IFNULL(CBCst,0)-IFNULL(NEW.BCst,0)
       WHERE Id=NEW.Ics_Id;
    Exception
      When OTHERS Then
        NULL;
    End;
  End If;
  Begin
    UPDATE Stor_SICS SET
           CQnt =IFNULL(CQnt ,0)-IFNULL(NEW.Qnt ,0),
           CWQnt=IFNULL(CWQnt,0)-IFNULL(NEW.WQnt,0),
           CCst =IFNULL(CCst ,0)-IFNULL(NEW.Cst ,0),
           CBCst=IFNULL(CBCst,0)-IFNULL(NEW.BCst,0)
     WHERE Id=NEW.SIcs_Id;
  Exception
    When OTHERS Then
      NULL;
  End;
Exception
  When No_Data_Found Then
