         CAmt =IFNULL(CAmt ,0)+IFNULL(NEW.Cst ,0),
         CBAmt=IFNULL(CBAmt,0)+IFNULL(NEW.BCst,0)
   Where Stor_Id=nStr
     And Item_Id=NEW.Item_Id;
  If NEW.TOrd_Id IS NOT NULL Then
    Update Stor_InOrdTrn Set
           CQnt=IFNULL(CQnt,0)+IFNULL(NEW.Qnt,0)
     Where Id=NEW.TOrd_Id;
  End If;
  Begin
    Select Id
      Into nIcsId
      From Stor_ICS
      WHERE Item_Id =    NEW.Item_Id
        AND LotSer  =IFNULL(NEW.LotSer  ,'_')
        AND Unit_Id =IFNULL(NEW.Unit_Id ,0  )
        AND Model_Id=IFNULL(NEW.Model_Id,0  )
        AND Size_Id =IFNULL(NEW.Size_Id ,0  )
        AND Color_Id=IFNULL(NEW.Color_Id,0  )
        AND nLength =IFNULL(NEW.nLength ,0  )
        AND nWidth  =IFNULL(NEW.nWidth  ,0  )
        AND nHeight =IFNULL(NEW.nHeight ,0  )
        AND SDate   =IFNULL(NEW.SDate,STR_TO_DATE('01-01-1900', '%d-%m-%Y'))
        AND EDate   =IFNULL(NEW.EDate,STR_TO_DATE('01-01-1900', '%d-%m-%Y'));
