          AND Model_Id=IFNULL(NEW.Model_Id,0  )
          AND Size_Id =IFNULL(NEW.Size_Id ,0  )
          AND Color_Id=IFNULL(NEW.Color_Id,0  )
          AND nLength =IFNULL(NEW.nLength ,0  )
          AND nWidth  =IFNULL(NEW.nWidth  ,0  )
          AND nHeight =IFNULL(NEW.nHeight ,0  )
          AND SDate   =IFNULL(NEW.SDate,STR_TO_DATE('01-01-1900', '%d-%m-%Y'))
          AND EDate   =IFNULL(NEW.EDate,STR_TO_DATE('01-01-1900', '%d-%m-%Y'));
      IF OLD.Ics_Id IS NOT NULL Then
        Begin
          UPDATE Stor_ICS SET
                 CQnt =IFNULL(CQnt ,0)-IFNULL(OLD.Qnt ,0),
                 CWQnt=IFNULL(CWQnt,0)-IFNULL(OLD.WQnt,0),
                 CCst =IFNULL(CCst ,0)-IFNULL(OLD.Cst ,0),
                 CBCst=IFNULL(CBCst,0)-IFNULL(OLD.BCst,0)
           WHERE Id=OLD.Ics_Id;
        Exception
          When OTHERS Then
            NULL;
        End;
      End IF;
      SET NEW.Ics_Id = nIcsId;
      IF NEW.Ics_Id IS NOT NULL Then
        Begin
          UPDATE Stor_ICS SET
                 CQnt =IFNULL(CQnt ,0)+IFNULL(NEW.Qnt ,0),
                 CWQnt=IFNULL(CWQnt,0)+IFNULL(NEW.WQnt,0),
                 CCst =IFNULL(CCst ,0)+IFNULL(NEW.Cst ,0),
                 CBCst=IFNULL(CBCst,0)+IFNULL(NEW.BCst,0)
           WHERE Id=NEW.Ics_Id;
        Exception
          When OTHERS Then
            NULL;
        End;
      End IF;
    Exception
