        IF OLD.Ics_Id IS NOT NULL Then
          Begin
            UPDATE Stor_ICS SET
                   CQnt =IFNULL(CQnt ,0)-IFNULL(OLD.Qnt ,0),
                   CWQnt=IFNULL(CWQnt,0)-IFNULL(OLD.WQnt,0),
                   CCst =IFNULL(CCst ,0)-IFNULL(OLD.Cst ,0),
                   CBCst=IFNULL(CBCst,0)-IFNULL(OLD.BCst,0)
             WHERE Id=OLD.Ics_Id;
          Exception
            When OTHERS Then
              NULL;
          End;
        End IF;
        Begin
          SELECT  CPrice,  NPrice,  DPrice,  SPrice,  WPrice,  RPrice,  HPrice,  MPrice
            INTO nCPrice, nNPrice, nDPrice, nSPrice, nWPrice, nRPrice, nHPrice, nMPrice
            FROM Stor_Item
           WHERE Id=NEW.Item_Id;
