      End;
    End IF;
  End IF;
Exception
  When No_Data_Found Then
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Undefined Item '||NEW.Item_Id||' In Store '||IFNULL(nStr,0)||' MstId='||NEW.Id;
