DELIMITER $$
CREATE TRIGGER
  Stor_TBU_TrTrn
  Before UPDATE ON Stor_TrTrn
  For Each Row
BEGIN
  DECLARE nFStr   DECIMAL(38,10);
  DECLARE nTStr   DECIMAL(38,10);
  DECLARE nCst    DECIMAL(38,10);
  DECLARE nBCst   DECIMAL(38,10);
  DECLARE nQnt    DECIMAL(38,10);
  DECLARE nBRate  DECIMAL(38,10) := 0;
  Select StorF_Id, StorT_Id, Decode(Sign(IFNULL(BCurn_Rate,1)), -1,1, 0,1, IFNULL(BCurn_Rate,1))
    Into nFStr   , nTStr   , nBRate
    From Stor_TrMst
    Where Id=NEW.Mst_Id;
  nQnt := 0;
  nCst := 0;
  Select IFNULL(CQnt,0), IFNULL(CAmt,0), IFNULL(CBAmt,0)
    Into     nQnt   ,     nCst   ,     nBCst
    From Stor_SMat
   Where Stor_Id=nFStr
     And Item_Id=NEW.Item_Id;
  If nQnt>0 Then
    nCst  := nCst  / nQnt;
    nBCst := nBCst / nQnt;
  End If;
  SET NEW.BAmt = Round(IFNULL(NEW.Amt,0) / nBRate, 2);
  SET NEW.Cst = nCst * NEW.Qnt;
  Update Stor_SMat Set
         CQnt =IFNULL(CQnt ,0)-(IFNULL(NEW.Qnt ,0)+IFNULL(OLD.Qnt ,0)),
         CAmt =IFNULL(CAmt ,0)-(IFNULL(NEW.Cst ,0)+IFNULL(OLD.Cst ,0)),
         CBAmt=IFNULL(CBAmt,0)-(IFNULL(NEW.BCst,0)+IFNULL(OLD.BCst,0))
   Where Stor_Id=nFStr
     And Item_Id=NEW.Item_Id;
  Update Stor_SMat Set
         CQnt =IFNULL(CQnt ,0)+(IFNULL(NEW.Qnt ,0)+IFNULL(OLD.Qnt ,0)),
         CAmt =IFNULL(CAmt ,0)+(IFNULL(NEW.Cst ,0)+IFNULL(OLD.Cst ,0)),
         CBAmt=IFNULL(CBAmt,0)+(IFNULL(NEW.BCst,0)+IFNULL(OLD.BCst,0))
   Where Stor_Id=nTStr
     And Item_Id=NEW.Item_Id;
  IF NEW.Ics_Id!=OLD.Ics_Id Then
    Begin
      UPDATE Stor_ICS SET
             CQnt =IFNULL(CQnt ,0)+IFNULL(OLD.Qnt ,0),
             CWQnt=IFNULL(CWQnt,0)+IFNULL(OLD.WQnt,0),
             CCst =IFNULL(CCst ,0)+IFNULL(OLD.Cst ,0),
             CBCst=IFNULL(CBCst,0)+IFNULL(OLD.BCst,0)
       WHERE Id=OLD.Ics_Id;
    Exception
      When OTHERS Then
        NULL;
    End;
    Begin
      UPDATE Stor_ICS SET
             CQnt =IFNULL(CQnt ,0)-IFNULL(NEW.Qnt ,0),
             CWQnt=IFNULL(CWQnt,0)-IFNULL(NEW.WQnt,0),
             CCst =IFNULL(CCst ,0)-IFNULL(NEW.Cst ,0),
             CBCst=IFNULL(CBCst,0)-IFNULL(NEW.BCst,0)
       WHERE Id=NEW.Ics_Id;
    Exception
      When OTHERS Then
        NULL;
    End;
  End IF;
  IF NEW.SIcs_FId!=OLD.SIcs_FId Then
    Begin
      UPDATE Stor_SICS SET
             CQnt =IFNULL(CQnt ,0)+IFNULL(OLD.Qnt ,0),
             CWQnt=IFNULL(CWQnt,0)+IFNULL(OLD.WQnt,0),
             CCst =IFNULL(CCst ,0)+IFNULL(OLD.Cst ,0),
             CBCst=IFNULL(CBCst,0)+IFNULL(OLD.BCst,0)
       WHERE Id=OLD.SIcs_FId;
    Exception
      When OTHERS Then
        NULL;
    End;
    Begin
      UPDATE Stor_SICS SET
             CQnt =IFNULL(CQnt ,0)-IFNULL(NEW.Qnt ,0),
             CWQnt=IFNULL(CWQnt,0)-IFNULL(NEW.WQnt,0),
             CCst =IFNULL(CCst ,0)-IFNULL(NEW.Cst ,0),
             CBCst=IFNULL(CBCst,0)-IFNULL(NEW.BCst,0)
       WHERE Id=NEW.SIcs_FId;
    Exception
      When OTHERS Then
        NULL;
    End;
  Else
    Begin
      UPDATE Stor_SICS SET
             CQnt =IFNULL(CQnt ,0)-(IFNULL(NEW.Qnt ,0)+IFNULL(OLD.Qnt ,0)),
             CWQnt=IFNULL(CWQnt,0)-(IFNULL(NEW.WQnt,0)+IFNULL(OLD.WQnt,0)),
             CCst =IFNULL(CCst ,0)-(IFNULL(NEW.Cst ,0)+IFNULL(OLD.Cst ,0)),
             CBCst=IFNULL(CBCst,0)-(IFNULL(NEW.BCst,0)+IFNULL(OLD.BCst,0))
       WHERE Id=NEW.SIcs_FId;
    Exception
      When OTHERS Then
        NULL;
    End;
  End IF;
  IF NEW.SIcs_TId!=OLD.SIcs_TId Then
    Begin
      UPDATE Stor_SICS SET
             CQnt =IFNULL(CQnt ,0)-IFNULL(OLD.Qnt ,0),
             CWQnt=IFNULL(CWQnt,0)-IFNULL(OLD.WQnt,0),
             CCst =IFNULL(CCst ,0)-IFNULL(OLD.Cst ,0),
             CBCst=IFNULL(CBCst,0)-IFNULL(OLD.BCst,0)
       WHERE Id=OLD.SIcs_TId;
    Exception
      When OTHERS Then
        NULL;
    End;
    Begin
      UPDATE Stor_SICS SET
             CQnt =IFNULL(CQnt ,0)+IFNULL(NEW.Qnt ,0),
             CWQnt=IFNULL(CWQnt,0)+IFNULL(NEW.WQnt,0),
             CCst =IFNULL(CCst ,0)+IFNULL(NEW.Cst ,0),
             CBCst=IFNULL(CBCst,0)+IFNULL(NEW.BCst,0)
       WHERE Id=NEW.SIcs_TId;
    Exception
      When OTHERS Then
        NULL;
    End;
  Else
    Begin
      UPDATE Stor_SICS SET
             CQnt =IFNULL(CQnt ,0)+(IFNULL(NEW.Qnt ,0)+IFNULL(OLD.Qnt ,0)),
             CWQnt=IFNULL(CWQnt,0)+(IFNULL(NEW.WQnt,0)+IFNULL(OLD.WQnt,0)),
             CCst =IFNULL(CCst ,0)+(IFNULL(NEW.Cst ,0)+IFNULL(OLD.Cst ,0)),
             CBCst=IFNULL(CBCst,0)+(IFNULL(NEW.BCst,0)+IFNULL(OLD.BCst,0))
       WHERE Id=NEW.SIcs_TId;
    Exception
      When OTHERS Then
        NULL;
    End;
  End IF;
Exception
  When No_Data_Found Then
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Undefined Item '||NEW.Item_Id||' In Store '||nFStr||', Store '||nTStr;
END$$
DELIMITER ;

